def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for a, b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == v and (a,b) not in seen:
                        seen.add((a,b)); q.append((a,b))
            rs = [x for x,y in cells]; cs = [y for x,y in cells]
            out.append((v, cells, max(rs)-min(rs)+1, max(cs)-min(cs)+1))
    return out

def transform(grid):
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    # Find the long, connected elbow-shaped marker.
    marker = None
    for v, cells, hh, ww in comps:
        if len(cells) < 7 or min(hh, ww) < 3:
            continue
        # L markers have long horizontal and vertical runs meeting at a corner.
        points = set(cells)
        corners = sum((r+1,c) in points and (r,c+1) in points for r,c in points)
        if corners:
            score = len(cells) + max(hh,ww)
            if marker is None or score > marker[0]: marker = (score,v,hh,ww)
    if marker is None:
        return out
    _, paint, mh, mw = marker
    vertical = mh >= mw
    candidates = []
    for v, cells, hh, ww in comps:
        if v == paint or len(cells) < 3:
            continue
        if (hh >= ww) == vertical:
            candidates.append((len(cells), cells))
    if candidates:
        _, cells = max(candidates, key=lambda x:x[0])
        for r,c in cells: out[r][c] = paint
    return out
"
}

